    def get(self) -> "Project":
        """Retrieve Project

        Retrieves a single project by id, including the governance policy it is
        enrolled in. The project must belong to the organization your API key is
        scoped to; one belonging to another organization is reported as not
        found rather than as forbidden.
        """
        payload = self._client.get(self._project_id())
        self._load(payload)
        return self

    async def a_get(self) -> "Project":
        """Retrieve Project

        Retrieves a single project by id, including the governance policy it is
        enrolled in. The project must belong to the organization your API key is
        scoped to; one belonging to another organization is reported as not
        found rather than as forbidden.
        """
        payload = await self._client.a_get(self._project_id())
        self._load(payload)
        return self

    def update(self) -> ProjectPayload:
        """Update Project

        Renames a project or changes its description, and returns the project as
        stored. Send at least one field; a field you omit is left as it is. A
        name already taken by another project in the organization is refused.
        """
        body = self._update_body()
        result = self._client.update(
            self._project_id(), name=body.name, description=body.description
        )
        self.project_id = result.id
        return result

    async def a_update(self) -> ProjectPayload:
        """Update Project

        Renames a project or changes its description, and returns the project as
        stored. Send at least one field; a field you omit is left as it is. A
        name already taken by another project in the organization is refused.
        """
        body = self._update_body()
        result = await self._client.a_update(
            self._project_id(), name=body.name, description=body.description
        )
        self.project_id = result.id
        return result

    def _update_body(self) -> UpdateProjectRequest:
        fields = {"name": self.name, "description": self.description}
        return UpdateProjectRequest(**fields)

    def _load(self, payload: ProjectPayload) -> None:
        self.id = payload.id
        self.name = payload.name
        self.description = payload.description
        self.organization_id = payload.organization_id
        self.created_at = payload.created_at
        self.governance_policy = payload.governance_policy

    def _project_id(self) -> str:
        if self.project_id is None:
            raise ValueError(
                "This project has no project_id. Initialize it with "
                "client.project(project_id=...), or create it first."
            )
        return self.project_id
